def specialPerm(nums: list[int]) -> int:
    n = len(nums)
    MOD = 10**9 + 7
    memo = {}
    def dfs(mask, last_idx):
        if mask == (1 << n) - 1: return 1
        state = (mask, last_idx)
        if state in memo: return memo[state]
        res = 0
        for j in range(n):
            if not (mask & (1 << j)):
                if last_idx == -1 or nums[j] % nums[last_idx] == 0 or nums[last_idx] % nums[j] == 0:
                    res = (res + dfs(mask | (1 << j), j)) % MOD
        memo[state] = res
        return res
    return dfs(0, -1)

